'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),G=require('./character-gear.js'),V=require('./character-vault.js');
test('reference requirements retain source version and never masquerade as verified target values',()=>{for(const [tier,level] of Object.entries({basic:17,enhanced:23,superior:29,mastercrafted:34,grandmaster:40})){for(const slot of Object.keys(G.slots)){const item=G.items['feline-'+slot+'-'+tier];assert.equal(item.referenceLevel,level);assert.equal(item.level,null);assert.equal(item.stats,null);assert.equal(item.provenance.version,'4.04');assert.equal(item.provenance.targetVerified,false);}}});
test('unknown levels remain unknown and low-level experiments remain selectable',()=>{const item=G.items['feline-chest-enhanced'];for(const v of [null,undefined,-1,NaN,Infinity,1.5])assert.equal(G.requirement(item,v).state,'profile-unknown');for(const [level,state] of [[22,'below-reference'],[23,'meets-reference'],[24,'meets-reference']]){const r=G.requirement(item,level);assert.equal(r.state,state);assert.equal(r.allowed,true);assert.match(r.text,/Current-version requirement not verified/);}});
test('a preview derives changed slots without mutating the current draft',()=>{const before=V.newBuild('x'),after=V.clone(before);after.equipment.chest='feline-chest-grandmaster';after.level=29;const changes=G.changes(before,after);assert.equal(changes.length,1);assert.equal(changes[0].slot,'chest');assert.equal(changes[0].before,null);assert.equal(changes[0].after.id,'feline-chest-grandmaster');assert.equal(changes[0].requirement.state,'below-reference');assert.equal(before.equipment.chest,null);});
test('all six whole-tier preview changes use the same shared catalogue and reference requirements',()=>{const before=V.newBuild('x'),after=V.clone(before);for(const slot of V.SLOTS)after.equipment[slot]='feline-'+slot+'-superior';assert.equal(G.changes(before,after).length,6);assert.ok(G.changes(before,after).every(x=>x.requirement.referenceLevel===29));});
test('the shared reference is deep-linkable and exposes all tiers without a DLC switch',()=>{const fs=require('node:fs'),ui=fs.readFileSync('character-ui.js','utf8'),page=fs.readFileSync('character.html','utf8');assert.ok(page.includes('id="catalogue-open"'));assert.ok(ui.includes("referenceRoute('#gear')"));assert.ok(ui.includes("a.href='#gear/'+item.id"));assert.ok(ui.includes('for(const tier of G.tiers)'));assert.ok(ui.includes("addEventListener('cancel'"));assert.ok(!/localStorage\.(setItem|removeItem|clear)/.test(ui));});
